class Solution {
public:
    bool removeOnes(vector<vector<int>>& grid) {
        int m = grid.size(), n = grid[0].size();
        for (int r = 1; r < m; ++r) {
            int flip = grid[r][0] ^ grid[0][0];
            for (int c = 0; c < n; ++c) {
                if ((grid[r][c] ^ grid[0][c]) != flip) return false;
            }
        }
        return true;
    }
};
